<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title><?= esc($title) ?></title></head><body><h1><?= esc($title) ?></h1>
<?php if ($validation && $validation->getErrors()): ?><ul><?php foreach ($validation->getErrors() as $error): ?><li><?= esc($error) ?></li><?php endforeach; ?></ul><?php endif; ?><?php if ($uploadError): ?><p><?= esc($uploadError) ?></p><?php endif; ?>
<form method="post" enctype="multipart/form-data"><?= csrf_field() ?><label>Username</label><br><input name="username" required value="<?= old('username', $user['username'] ?? '') ?>"><br><br><label>Full Name</label><br><input name="full_name" required value="<?= old('full_name', $user['full_name'] ?? '') ?>"><br><br><?php if (!empty($user['avatar'])): ?><img src="<?= base_url('uploads/' . $user['avatar']) ?>" alt="Current avatar" width="120" height="120"><br><br><?php endif; ?><label>Profile Picture (JPG or PNG, maximum 2MB)</label><br><input type="file" name="avatar" accept="image/jpeg,image/png"><br><br><button type="submit">Save User</button></form><p><a href="<?= base_url('accounts/users') ?>">Back</a></p></body></html>
